{"implementation": "def solve(case):
    lines = case["lines"]
    trajectory = []
    for line in lines:
        parts = line.split(":", 1)
        if len(parts) != 2:
            trajectory.append({"type": "malformed", "content": line})
        else:
            typ = parts[0].strip()
            content = parts[1].strip()
            trajectory.append({"type": typ, "content": content})
    n = len(trajectory)
    error_line = None
    valid = True
    if n == 0:
        valid = False
        error_line = 0
    else:
        if trajectory[0]["type"] != "Thought":
            valid = False
            error_line = 0
        else:
            for i in range(1, n):
                prev_type = trajectory[i-1]["type"]
                curr_type = trajectory[i]["type"]
                allowed_next = []
                if prev_type == "Thought":
                    allowed_next = ["Action", "Final"]
                elif prev_type == "Action":
                    allowed_next = ["Observation"]
                elif prev_type == "Observation":
                    allowed_next = ["Thought"]
                elif prev_type == "Final":
                    allowed_next = []
                else:
                    pass
                if curr_type not in allowed_next:
                    valid = False
                    error_line = i
                    break
            if valid and n > 0:
                if trajectory[-1]["type"] != "Final":
                    valid = False
                    error_line = n - 1
    return {
        "valid": valid,
        "error_line": error_line,
        "trajectory": trajectory
    }"}
